import type { Lang } from "@/lib/i18n";

export type BlogCategory = "news" | "ferrari" | "lamborghini" | "porsche";
export type VehicleRef = { city: string; match: string };
export type BlogTranslation = { title: string; excerpt: string; intro: string; sections: { title: string; paragraphs: string[] }[]; cta: string };
export type BlogPost = { slug: string; date: string; category: BlogCategory; cover: VehicleRef; coverImage?: string; vehicles: VehicleRef[]; cities: string[]; brand: string; sources: { name: string; url?: string }[]; description?: Record<Lang, string>; inlineLinks?: { slug?: string; path?: string; phrase: Record<Lang, string> }[]; translations: Record<Lang, BlogTranslation> };
const tr = (pt: string, en: string, es: string): Record<Lang, string> => ({ pt, en, es });
const section = (title: Record<Lang, string>, ...paragraphs: Record<Lang, string>[]) => ({ title, paragraphs });
function copy(title: Record<Lang, string>, excerpt: Record<Lang, string>, intro: Record<Lang, string>, sections: ReturnType<typeof section>[], cta: Record<Lang, string>): Record<Lang, BlogTranslation> {
  return Object.fromEntries((["pt", "en", "es"] as const).map(l => [l, { title: title[l], excerpt: excerpt[l], intro: intro[l], sections: sections.map(s => ({ title: s.title[l], paragraphs: s.paragraphs.map(p => p[l]) })), cta: cta[l] }])) as Record<Lang, BlogTranslation>;
}
const rentalCta = (model: string, cities: string) => tr(
  `Quer dirigir ${model} em ${cities}? Conheça as unidades do catálogo da Onic Car Rentals e converse com nossa equipe. Atendimento em português e um processo pensado para minimizar a burocracia, sem dispensar os documentos e as condições da reserva. Consulte o modelo ou a frota e fale conosco pelo WhatsApp.`,
  `Would you like to drive ${model} in ${cities}? Explore the Onic Car Rentals catalog and talk to our team. Portuguese-speaking support and a process designed to keep bureaucracy to a minimum, without bypassing booking documents or conditions. View the model or fleet and contact us on WhatsApp.`,
  `¿Quieres conducir ${model} en ${cities}? Conoce las unidades del catálogo de Onic Car Rentals y habla con nuestro equipo. Atención en portugués y un proceso pensado para minimizar la burocracia, sin omitir los documentos ni las condiciones de reserva. Consulta el modelo o la flota y escríbenos por WhatsApp.`
);

